mapper.delete:
delete from RSK_FACILITY_ADJ_PLAN
where FACILITY_ID = #{facilityId,jdbcType=VARCHAR}
  and FACILITY_ADJ_START_DATE = #{facilityAdjStartDate,jdbcType=DATE}

mapper.update:
update RSK_FACILITY_ADJ_PLAN
